import{_ as e,c as n,o as r,a0 as i}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Arbeitsblätter für mentale Spiele","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/de/exercise-worksheets.md","filePath":"public/downloads/de/exercise-worksheets.md"}');const _=e({name:"public/downloads/de/exercise-worksheets.md"},[["render",function(e,t,_,a,l,s){return r(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="arbeitsblatter-fur-mentale-spiele" tabindex="-1">Arbeitsblätter für mentale Spiele <a class="header-anchor" href="#arbeitsblatter-fur-mentale-spiele" aria-label="Permalink to &quot;Arbeitsblätter für mentale Spiele&quot;">​</a></h1><p><strong>Pétanque-Akademie - Praktische Übungen</strong></p><hr><h2 id="ubung-1-reflexion-des-stromungszustands" tabindex="-1">Übung 1: Reflexion des Strömungszustands <a class="header-anchor" href="#ubung-1-reflexion-des-stromungszustands" aria-label="Permalink to &quot;Übung 1: Reflexion des Strömungszustands&quot;">​</a></h2><h3 id="wann-haben-sie-den-flow-zustand-erlebt" tabindex="-1">Wann haben Sie den Flow-Zustand erlebt? <a class="header-anchor" href="#wann-haben-sie-den-flow-zustand-erlebt" aria-label="Permalink to &quot;Wann haben Sie den Flow-Zustand erlebt?&quot;">​</a></h3><p>Denken Sie an eine Zeit, in der Sie Ihr bestes Boule-Spiel gespielt haben:</p><p><strong>Beschreiben Sie die Situation:</strong></p><ul><li>Um welches Turnier/Spiel handelte es sich?</li><li>Wie waren die Bedingungen?</li><li>Mit wem hast du gespielt?</li></ul><hr><hr><p><strong>Wie hat es sich angefühlt?</strong></p><ul><li>Wie war Ihr psychischer Zustand?</li><li>Wie hat sich die Zeit angefühlt?</li><li>Woran hast du gedacht (oder was hast du nicht gedacht)?</li></ul><hr><hr><p><strong>Was hat Ihnen dabei geholfen, dorthin zu gelangen?</strong></p><ul><li>Was hast du vor dem Spiel gemacht?</li><li>Was war an diesem Tag anders?</li><li>Können Sie eine dieser Bedingungen nachstellen?</li></ul><hr><hr><hr><h2 id="ubung-2-inventar-des-inneren-kritikers" tabindex="-1">Übung 2: Inventar des inneren Kritikers <a class="header-anchor" href="#ubung-2-inventar-des-inneren-kritikers" aria-label="Permalink to &quot;Übung 2: Inventar des inneren Kritikers&quot;">​</a></h2><h3 id="identifiziere-deinen-inneren-kritiker" tabindex="-1">Identifiziere deinen inneren Kritiker <a class="header-anchor" href="#identifiziere-deinen-inneren-kritiker" aria-label="Permalink to &quot;Identifiziere deinen inneren Kritiker&quot;">​</a></h3><p><strong>Was sagt dein innerer Kritiker?</strong></p><p>Nennen Sie 3-5 häufige kritische Gedanken, die Ihnen während eines Wettkampfs kommen:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>Wann erscheint es?</strong></p><ul><li>Nach Fehlern? □</li><li>Vor wichtigen Aufnahmen? □</li><li>Beim Spielen gegen starke Gegner? □</li><li>Wenn die Teamkollegen zusehen? □</li><li>Andere: _______________________________________________</li></ul><hr><h2 id="ubung-3-umdeutungspraxis" tabindex="-1">Übung 3: Umdeutungspraxis <a class="header-anchor" href="#ubung-3-umdeutungspraxis" aria-label="Permalink to &quot;Übung 3: Umdeutungspraxis&quot;">​</a></h2><h3 id="vom-kritiker-zum-coach" tabindex="-1">Vom Kritiker zum Coach <a class="header-anchor" href="#vom-kritiker-zum-coach" aria-label="Permalink to &quot;Vom Kritiker zum Coach&quot;">​</a></h3><p><strong>Schreibe für jeden Gedanken des inneren Kritikers eine Umformulierung durch den inneren Coach:</strong></p><table tabindex="0"><thead><tr><th>Innerer Kritiker</th><th>Innerer Coach</th></tr></thead><tbody><tr><td>Beispiel: „Unter Druck mache ich immer Fehler.“</td><td>„Ich habe schon einmal unter Druck Erfolg gehabt, ich kann es wieder schaffen.“</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Üben Sie, diese Sätze laut auszusprechen.</strong></p><hr><h2 id="ubung-4-gestaltung-der-vorbereitungsroutine-vor-dem-wurf" tabindex="-1">Übung 4: Gestaltung der Vorbereitungsroutine vor dem Wurf <a class="header-anchor" href="#ubung-4-gestaltung-der-vorbereitungsroutine-vor-dem-wurf" aria-label="Permalink to &quot;Übung 4: Gestaltung der Vorbereitungsroutine vor dem Wurf&quot;">​</a></h2><h3 id="erstelle-deine-personliche-routine" tabindex="-1">Erstelle deine persönliche Routine <a class="header-anchor" href="#erstelle-deine-personliche-routine" aria-label="Permalink to &quot;Erstelle deine persönliche Routine&quot;">​</a></h3><p>Entwerfen Sie eine 4-stufige Vorbereitungsroutine, die für Sie funktioniert:</p><p><strong>Schritt 1: Visualisieren</strong></p><ul><li>Was genau werden Sie visualisieren?</li><li>Wie lange (2-3 Sekunden)?</li></ul><hr><p><strong>Schritt 2: Atmen</strong></p><ul><li>Einmal oder dreimal tief durchatmen?</li><li>Gibt es ein bestimmtes Muster?</li></ul><hr><p><strong>Schritt 3: Verankern</strong></p><ul><li>Welchen physischen Ankerpunkt werden Sie verwenden?</li><li>Boule-Spiel mit Berührung? Bestimmte Haltung?</li></ul><hr><p><strong>Schritt 4: Ausführen</strong></p><ul><li>Was ist Ihr mentaler Auslöser?</li><li>&quot;Vertrauen&quot; / &quot;Flow&quot; / &quot;Los&quot;?</li></ul><hr><p><strong>Üben Sie diese Übung heute 10 Mal.</strong></p><hr><h2 id="ubung-5-druckausloser" tabindex="-1">Übung 5: Druckauslöser <a class="header-anchor" href="#ubung-5-druckausloser" aria-label="Permalink to &quot;Übung 5: Druckauslöser&quot;">​</a></h2><h3 id="identifizieren-sie-ihre-druckpunkte" tabindex="-1">Identifizieren Sie Ihre Druckpunkte <a class="header-anchor" href="#identifizieren-sie-ihre-druckpunkte" aria-label="Permalink to &quot;Identifizieren Sie Ihre Druckpunkte&quot;">​</a></h3><p>Welche Situationen setzen Sie unter Druck?</p><p>Bewerten Sie jeden Wert von 1 (kein Druck) bis 10 (extremer Druck):</p><ul><li>Spiel gegen starke Gegner: ___/10</li><li>Wichtige Turnierspiele: ___/10</li><li>Unentschieden, letzter Schuss: ___/10</li><li>Nach einem Fehler: ___/10</li><li>Wenn die Teamkollegen zusehen: ___/10</li><li>Wenn ich schlecht spiele: ___/10</li><li>Sonstiges: _________________________ ___/10</li></ul><p><strong>Für Ihren am besten bewerteten Trigger:</strong></p><p>Welche körperlichen Empfindungen nehmen Sie wahr?</p><hr><p>Welche Gedanken tauchen auf?</p><hr><p>Welche Technik werden Sie anwenden?</p><ul><li>[ ] 3-Atemzug-Reset</li><li>[ ] Vorbereitende Routine</li><li>[ ] Umdeutung</li><li>[ ] Andere: _____________________</li></ul><hr><h2 id="ubung-6-moduswechselubung" tabindex="-1">Übung 6: Moduswechselübung <a class="header-anchor" href="#ubung-6-moduswechselubung" aria-label="Permalink to &quot;Übung 6: Moduswechselübung&quot;">​</a></h2><h3 id="planung-vs-ausfuhrung" tabindex="-1">Planung vs. Ausführung <a class="header-anchor" href="#planung-vs-ausfuhrung" aria-label="Permalink to &quot;Planung vs. Ausführung&quot;">​</a></h3><p><strong>Üben Sie den Wechsel:</strong></p><p><strong>Planungsphase (Vor dem Shooting):</strong></p><ul><li>Was muss ich analysieren?</li><li>Was ist meine Strategie?</li><li>Welchen Schuss werde ich wählen?</li></ul><p><strong>Ausführungsphase (Während der Aufnahme):</strong></p><ul><li>Mach dir den Kopf frei</li><li>Vertraue deinem Körper</li><li>Lass es geschehen</li></ul><p><strong>Übungsaufgabe:</strong></p><p>Machen Sie 5 Probeschüsse. Für jeden:</p><ol><li>Verbringen Sie 10 Sekunden im Planungsmodus (analysieren, entscheiden).</li><li>Atmen Sie dreimal tief durch, um den Modus zu wechseln.</li><li>Im Flow-Modus ausführen (ohne nachzudenken)</li></ol><p><strong>Spiegelung:</strong></p><ul><li>Konntest du den Unterschied zwischen den Modi spüren?</li><li>War der Schalter frei?</li><li>Welcher Modus fällt Ihnen schwerer?</li></ul><hr><hr><hr><h2 id="ubung-7-wochentlicher-ubungsplan" tabindex="-1">Übung 7: Wöchentlicher Übungsplan <a class="header-anchor" href="#ubung-7-wochentlicher-ubungsplan" aria-label="Permalink to &quot;Übung 7: Wöchentlicher Übungsplan&quot;">​</a></h2><h3 id="schwerpunkt-dieser-woche" tabindex="-1">Schwerpunkt dieser Woche <a class="header-anchor" href="#schwerpunkt-dieser-woche" aria-label="Permalink to &quot;Schwerpunkt dieser Woche&quot;">​</a></h3><p><strong>Wähle EINE Technik zum Üben aus:</strong></p><ul><li>[ ] 3-Atemzüge: Nach jedem Fehler zurücksetzen</li><li>[ ] Vorwurf-Routine bei jedem Wurf</li><li>[ ] Pro Sitzung einen Gedanken des inneren Kritikers umformulieren</li><li>[ ] Übungsmodus-Umschaltung</li></ul><p><strong>Tägliche Übung:</strong></p><table tabindex="0"><thead><tr><th>Tag</th><th>Übungsaktivität</th><th>Dauer</th><th>Hinweise</th></tr></thead><tbody><tr><td>Mo</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Di</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Mi</td><td>________________</td><td>___ Min.</td><td>________________</td></tr><tr><td>Do</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Fr</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sa</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sonne</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="ubung-8-fortschrittsverfolgung" tabindex="-1">Übung 8: Fortschrittsverfolgung <a class="header-anchor" href="#ubung-8-fortschrittsverfolgung" aria-label="Permalink to &quot;Übung 8: Fortschrittsverfolgung&quot;">​</a></h2><h3 id="wochenruckblick" tabindex="-1">Wochenrückblick <a class="header-anchor" href="#wochenruckblick" aria-label="Permalink to &quot;Wochenrückblick&quot;">​</a></h3><p><strong>Was hast du diese Woche geübt?</strong></p><hr><p><strong>Was ist Ihnen aufgefallen?</strong></p><hr><hr><p><strong>Was hat gut funktioniert?</strong></p><hr><hr><p><strong>Was war die Herausforderung?</strong></p><hr><hr><p><strong>Was werden Sie nächste Woche fortsetzen?</strong></p><hr><hr><p><strong>Was werden Sie anpassen?</strong></p><hr><hr><hr><h2 id="nachste-schritte" tabindex="-1">Nächste Schritte <a class="header-anchor" href="#nachste-schritte" aria-label="Permalink to &quot;Nächste Schritte&quot;">​</a></h2><h3 id="setzen-sie-ihre-entwicklung-fort" tabindex="-1">Setzen Sie Ihre Entwicklung fort <a class="header-anchor" href="#setzen-sie-ihre-entwicklung-fort" aria-label="Permalink to &quot;Setzen Sie Ihre Entwicklung fort&quot;">​</a></h3><p><strong>Ressourcen auf carreau.app:</strong></p><ul><li>Zielvorlage – Strukturieren Sie Ihre langfristige Entwicklung</li><li>Tagebuchvorlage – Täglichen Fortschritt verfolgen</li><li>Die Zone – Tiefer Einblick in Flow-Zustände</li><li>Mentale Stärke – Fortgeschrittenes Druckmanagement</li></ul><p><strong>Üben Sie weiter:</strong></p><ul><li>Mentale Fähigkeiten benötigen regelmäßiges Training.</li><li>Fang klein an und baue schrittweise auf.</li><li>Verfolge deinen Fortschritt</li><li>Verbesserungen feiern</li></ul><hr><p><em>Pétanque Academy – Elite-Spielerentwicklung</em><em>carreau.app</em></p>',113)])])}]]);export{t as __pageData,_ as default};
